on conflict (country_code, calendar_code, calendar_date)
do update set
  language_code = excluded.language_code,
  feast_rank = excluded.feast_rank,
  saints = excluded.saints,
  title = excluded.title,
  details = excluded.details,
  fasting_note = excluded.fasting_note,
  editorial_source = excluded.editorial_source,
  is_published = excluded.is_published,
  updated_at = timezone('utc', now());

-- Validation guard: both Moldova calendars must be complete civil-year calendars.
do $$
declare
  v_count integer;
  v_unique integer;
  v_min date;
  v_max date;
begin
  for v_count, v_unique, v_min, v_max in
    select count(*), count(distinct calendar_date), min(calendar_date), max(calendar_date)
    from public.calendar_days
    where country_code = 'MD'
      and calendar_code in ('md-basarabia', 'md-chisinau')
      and calendar_date between '2026-01-01' and '2026-12-31'
    group by calendar_code
  loop
    if v_count <> 365 or v_unique <> 365 or v_min <> '2026-01-01' or v_max <> '2026-12-31' then
      raise exception 'Invalid Moldova 2026 calendar: count %, unique %, first %, last %', v_count, v_unique, v_min, v_max;
    end if;
  end loop;
end $$;
